import React, {useEffect, useState} from "react";
import ImageWithBasePath from "../../../core/common/imageWithBasePath";
import DateRangePicker from "react-bootstrap-daterangepicker";
import Chart from "react-apexcharts";
import { Link } from "react-router-dom";
import { all_routes } from "../../router/all_routes";
import CollapseHeader from "../../../core/common/collapse-header";
import { endpoints } from "../../../helper/endpoints";
import PrivateServer from "../../../helper/PrivateServer";
import moment from "moment";
import _ from "lodash"
import ApexCharts from "apexcharts";
window.ApexCharts = ApexCharts;

const route = all_routes;
const LeadsDashboard = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [searchTermPie, setSearchTermPie] = useState('');
  const [searchTermGraph, setSearchTermGraph] = useState('');
  const [leads, setLeads] = useState([]);
  const [searchData, setFilteredSearchData] = useState([]);
  const [chartOptions] = useState<any>( {
    series: [
      {
        data: [400, 220, 448],
        color: "#FC0027",
      },
    ],
    chart: {
      type: "bar",
      height: 150,
    },
    plotOptions: {
      bar: {
        horizontal: true,
      },
    },
    dataLabels: {
      enabled: false,
    },
    xaxis: {
      categories: ["Conversation", "Follow Up", "Inpipeline"],
      min: 0,  
          max: 500,  
          tickAmount: 5,  
    },
  });
  const [chartOptions2] = useState<any>( {
    series: [
      {
        data: [400, 220, 448],
        color: "#77D882",
      },
    ],
    chart: {
      type: "bar",
      height: 150,
    },
    plotOptions: {
      bar: {
        horizontal: true,
      },
    },
    dataLabels: {
      enabled: false,
    },
    xaxis: {
      categories: ["Conversation", "Follow Up", "Inpipeline"],
      min: 0,  
          max: 500,  
          tickAmount: 5,  
    },
  });
  const [chartOptions3, setChartOptions3] = useState<any>({
    series: [],
    options: {
      chart: {
        width: 400,
        height: 300,
        type: "pie",
      },
      legend: {
        position: "bottom",
      },
      labels: [],
      responsive: [
        {
          breakpoint: 480,
          options: {
            chart: {
              width: 275,
            },
            legend: {
              position: "bottom",
            },
          },
        },
      ],
    },
  });

  const chartElement = document.querySelector("#leadpiechart");
  if (chartElement) {
    const options = {
      series: chartOptions3.series,
      chart: {
        width: 400,
        type: "pie",
      },
      legend: {
        position: "bottom",
      },
      labels: chartOptions3.options.labels,
      responsive: chartOptions3.options.responsive,
    };

    const chart = new ApexCharts(chartElement, options);
    chart.render();
  }

  const [chartOptions4, setChartOptions4] = useState<any>( {
    series: [],
    colors: ["#4A00E5"],
    chart: {
      height: 273,
      type: "area",
      zoom: {
        enabled: false,
      },
    },
    dataLabels: {
      enabled: false,
    },
    title: {
      text: "",
      align: "left",
    },
    xaxis: {
      categories: [
        "Jan",
        "Feb",
        "Mar",
        "Apr",
        "May",
        "Jun",
        "Jul",
        "Aug",
        "Sep",
        "Oct",
        "Nov",
        "Dec",
      ],
    },
    yaxis: {
      min: 10,
      max: 60,
      tickAmount: 5,
    },
    legend: {
      position: "top",
      horizontalAlign: "left",
    },
  });


  const initialSettings = {
    endDate: new Date("2020-08-11T12:30:00.000Z"),
    ranges: {
      "Last 30 Days": [
        new Date("2020-07-12T04:57:17.076Z"),
        new Date("2020-08-10T04:57:17.076Z"),
      ],
      "Last 7 Days": [
        new Date("2020-08-04T04:57:17.076Z"),
        new Date("2020-08-10T04:57:17.076Z"),
      ],
      "Last Month": [
        new Date("2020-06-30T18:30:00.000Z"),
        new Date("2020-07-31T18:29:59.999Z"),
      ],
      "This Month": [
        new Date("2020-07-31T18:30:00.000Z"),
        new Date("2020-08-31T18:29:59.999Z"),
      ],
      Today: [
        new Date("2020-08-10T04:57:17.076Z"),
        new Date("2020-08-10T04:57:17.076Z"),
      ],
      Yesterday: [
        new Date("2020-08-09T04:57:17.076Z"),
        new Date("2020-08-09T04:57:17.076Z"),
      ],
    },
    startDate: new Date("2020-08-04T04:57:17.076Z"), // Set "Last 7 Days" as default
    timePicker: false,
  };

  const getDeals = async () => {
    try {
      const { Deals } = endpoints;
      const response = await PrivateServer.getData(Deals?.view)
  
      if(response?.data) {
        setLeads(response?.data);

        setChartOptions3({
          ...chartOptions3, 
          series: [...new Set(response?.data?.map((x) => x?.stage?.stage_percentage?.[0]))],
          options: {
            ...chartOptions3.options,
            labels: [...new Set(response?.data?.map((x) => x?.stage?.pipeline_name))],
          },
        })

        setChartOptions4({
          ...chartOptions4, 
          series: [...new Set(response?.data?.map((x) => ({ name: "Reports", data: [x?.stage?.stage_percentage?.[0]] })))],
        })
      }
    } catch(error) {
      console.log("Error while getting deals -- E:", error?.message);
    }
  }

  const filterByLastXDays = (data: any[], days: number) => {
    const cutoff = moment().subtract(days, 'days').startOf('day');

    return _.filter(data, (item) => {
      return moment(item.last_contact_date).isAfter(cutoff);
    });
  };

  const handleSearch = (_days) => {
    setSearchTerm(_days);
    setSearchTermPie(_days);
    setSearchTermGraph(_days);

    const _filterdData = filterByLastXDays(leads, parseInt(_days));

    if(_days != '0') setFilteredSearchData(_filterdData);
    else setFilteredSearchData(leads)
  }

  useEffect(() => {
    getDeals();
  }, [])

  return (
    <div>
      {/* Page Wrapper */}
      <div className="page-wrapper">
  <div className="content">
    <div className="row">
      <div className="col-md-12">
        <div className="page-header">
          <div className="row align-items-center ">
            <div className="col-md-4">
              <h3 className="page-title">Leads Dashboard</h3>
            </div>
            <div className="col-md-8 float-end ms-auto">
              <div className="d-flex title-head">
                <div className="daterange-picker d-flex align-items-center justify-content-center">
                  <div className="form-sort me-2">
                    <i className="ti ti-calendar" />
                    <DateRangePicker
                                initialSettings={initialSettings}
                              >
                                <input
                                  className="form-control bookingrange"
                                  type="text"
                                />
                              </DateRangePicker>
                  </div>
                  <div className="head-icons mb-0">
                    <CollapseHeader/>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
    <div className="row">
      <div className="col-md-7">
        <div className="card">
          <div className="card-header border-0 pb-0">
            <div className="d-flex align-items-center justify-content-between flex-wrap row-gap-3">
              <h4>
                <i className="ti ti-grip-vertical me-1" />
                Recently Created Leads
              </h4>
              <div className="dropdown">
                <button
                  className="dropdown-toggle"
                  data-bs-toggle="dropdown"
                  onClick={() => {}}
                >
                  <i className="ti ti-calendar-check me-2" />
                  {searchTerm != "" ? `Last ${searchTerm} days` : 'Recent data'}
                </button>
                <div className="dropdown-menu dropdown-menu-end">
                  <button className="dropdown-item" onClick={() => handleSearch('0')}>
                    Recent data
                  </button>
                  <button className="dropdown-item" onClick={() => handleSearch('15')}>
                    Last 15 days
                  </button>
                  <button className="dropdown-item" onClick={() => handleSearch('30')}>
                    Last 30 days
                  </button>
                </div>
              </div>
            </div>
          </div>
          <div className="card-body">
            <div className="table-responsive custom-table">
              <table className="table dataTable" id="lead-project">
                <thead className="thead-light">
                  <tr>
                    <th>Lead Name</th>
                    <th>Company Name</th>
                    <th>Phone</th>
                    <th>Lead Status</th>
                  </tr>
                </thead>
                <tbody>
                  {
                    searchTerm != '' ? searchData?.filter((_, i) => i < 5)?.map((_lead) => (
                      <>
                        <tr className="odd" key={_lead?._id}>
                          <td>{_lead?.description}</td>
                          <td>
                            <h2 className="d-flex align-items-center"> 
                              <Link
                                to={route.companyDetails}
                                state={{ ..._lead?.company_name, totalData: leads?.length }}
                                className="d-flex flex-column"
                              >
                                {_lead?.company_name?.company_name}<span className="text-default">{_lead?.company_name?.city}, {_lead?.company_name?.country}</span>
                              </Link>
                            </h2>
                          </td>
                          <td>{_lead?.contact_name?.first_name} - {_lead?.contact_name?.primary_phone}</td>
                          <td>
                            <span className={`badge badge-pill ${_lead?.stage?.stage_percentage?.[0] == '100' ? 'bg-success' : _lead?.stage?.stage_percentage?.[0] == '50' ? 'bg-warning' :_lead?.stage?.stage_percentage?.[0] == '75' ? 'bg-info' : 'bg-pending'}`}>
                              {" "}
                              {_lead?.stage?.pipeline_name} ({_lead?.stage?.stage_percentage?.[0]})
                            </span>
                          </td>
                        </tr>
                      </>
                    )) 
                    :
                    leads?.filter((_, i) => i < 5)?.map((_lead) => (
                      <>
                        <tr className="odd">
                          <td>{_lead?.description}</td>
                          <td>
                            <h2 className="d-flex align-items-center"> 
                              <Link
                                to={route.companyDetails}
                                state={{ ..._lead?.company_name, totalData: leads?.length }}
                                className="d-flex flex-column"
                              >
                                {_lead?.company_name?.company_name}<span className="text-default">{_lead?.company_name?.city}, {_lead?.company_name?.country}</span>
                              </Link>
                            </h2>
                          </td>
                          <td>{_lead?.contact_name?.first_name} - {_lead?.contact_name?.primary_phone}</td>
                          <td>
                            <span className={`badge badge-pill ${_lead?.stage?.stage_percentage?.[0] == '100' ? 'bg-success' : _lead?.stage?.stage_percentage?.[0] == '50' ? 'bg-warning' :_lead?.stage?.stage_percentage?.[0] == '75' ? 'bg-info' : 'bg-pending'}`}>
                              {" "}
                              {_lead?.stage?.pipeline_name} ({_lead?.stage?.stage_percentage?.[0]})
                            </span>
                          </td>
                        </tr>
                      </>
                    ))
                  }
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
      <div className="col-md-5 d-flex">
        <div className="card w-100">
          <div className="card-header border-0 pb-0">
            <div className="d-flex align-items-center justify-content-between flex-wrap row-gap-3">
              <h4>
                <i className="ti ti-grip-vertical me-1" />
                Projects By Stage
              </h4>
              <div className="dropdown">
                <button
                  className="dropdown-toggle"
                  data-bs-toggle="dropdown"
                >
                  {searchTermPie != "" ? `Last ${searchTermPie} days` : 'Recent Data'}
                </button>
                <div className="dropdown-menu dropdown-menu-end">
                  <button className="dropdown-item" onClick={() => handleSearch('0')}>
                    Recent Data
                  </button>
                  <button className="dropdown-item" onClick={() => handleSearch('30')}>
                    Last 30 Days
                  </button>
                  <button className="dropdown-item" onClick={() => handleSearch('15')}>
                    Last 15 Days
                  </button>
                  <button className="dropdown-item" onClick={() => handleSearch('7')}>
                    Last 7 Days
                  </button>
                </div>
              </div>
            </div>
          </div>
          <div className="card-body">
          <div id="leadpiechart">
          <Chart
            options={chartOptions3?.options}
            series={chartOptions3?.series}
            type="pie"
            width={chartOptions3.options.chart.width}
            height={chartOptions3.options.chart.height}
          />
    </div>
          </div>
        </div>
      </div>
    </div>
    <div className="row">
      <div className="col-md-12 d-flex">
        <div className="card w-100">
          <div className="card-header border-0 pb-0">
            <div className="d-flex align-items-center justify-content-between flex-wrap row-gap-3">
              <h4>
                <i className="ti ti-grip-vertical me-1" />
                Projects By Stage
              </h4>
              <div className="d-flex align-items-center flex-wrap row-gap-2">
                <div className="dropdown">
                  <button
                    className="dropdown-toggle"
                    data-bs-toggle="dropdown"
                  >
                    {searchTermPie != "" ? `Last ${searchTermPie} days` : 'Recent Data'}
                  </button>
                  <div className="dropdown-menu dropdown-menu-end">
                    <button className="dropdown-item" onClick={() => handleSearch('0')}>
                      Recent Data
                    </button>
                    <button className="dropdown-item" onClick={() => handleSearch('30')}>
                      Last 30 Days
                    </button>
                    <button className="dropdown-item" onClick={() => handleSearch('15')}>
                      Last 15 Days
                    </button>
                    <button className="dropdown-item" onClick={() => handleSearch('7')}>
                      Last 7 Days
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
          <div className="card-body">
          <div id="contact-report">
                        <Chart
                        options={chartOptions4}
                          series={chartOptions4?.series}
                          type="area"
                          height={chartOptions4.chart.height}
                        />
                      </div>
          </div>
        </div>
      </div>
      {/* <div className="col-md-6">
        <div className="card">
          <div className="card-header border-0 pb-0">
            <div className="d-flex align-items-center justify-content-between flex-wrap row-gap-3">
              <h4>
                <i className="ti ti-grip-vertical me-1" />
                Leads By Stage
              </h4>
              <div className="d-flex align-items-center flex-wrap row-gap-2">
                <div className="dropdown me-2">
                  <Link
                    className="dropdown-toggle"
                    data-bs-toggle="dropdown"
                    to="#"
                  >
                    Marketing Pipeline
                  </Link>
                  <div className="dropdown-menu dropdown-menu-end">
                    <Link to="#" className="dropdown-item">
                      Marketing Pipeline
                    </Link>
                    <Link to="#" className="dropdown-item">
                      Sales Pipeline
                    </Link>
                    <Link to="#" className="dropdown-item">
                      Email
                    </Link>
                    <Link to="#" className="dropdown-item">
                      Chats
                    </Link>
                    <Link to="#" className="dropdown-item">
                      Operational
                    </Link>
                  </div>
                </div>
                <div className="dropdown">
                  <Link
                    className="dropdown-toggle"
                    data-bs-toggle="dropdown"
                    to="#"
                  >
                    Last 3 months
                  </Link>
                  <div className="dropdown-menu dropdown-menu-end">
                    <Link to="#" className="dropdown-item">
                      Last 3 months
                    </Link>
                    <Link to="#" className="dropdown-item">
                      Last 6 months
                    </Link>
                    <Link to="#" className="dropdown-item">
                      Last 12 months
                    </Link>
                  </div>
                </div>
              </div>
            </div>
          </div>
          <div className="card-body">
          <div id="last-chart">
                        <Chart
                          options={chartOptions}
                          series={chartOptions.series}
                          type={chartOptions.chart.type}
                          height={chartOptions.chart.height}
                        />
                      </div>
          </div>
        </div>
      </div>
      <div className="col-md-6">
        <div className="card">
          <div className="card-header border-0 pb-0">
            <div className="d-flex align-items-center justify-content-between flex-wrap row-gap-3">
              <h4>
                <i className="ti ti-grip-vertical me-1" />
                Won Deals Stage
              </h4>
              <div className="d-flex align-items-center flex-wrap row-gap-2">
                <div className="dropdown me-2">
                  <Link
                    className="dropdown-toggle"
                    data-bs-toggle="dropdown"
                    to="#"
                  >
                    Marketing Pipeline
                  </Link>
                  <div className="dropdown-menu dropdown-menu-end">
                    <Link to="#" className="dropdown-item">
                      Marketing Pipeline
                    </Link>
                    <Link to="#" className="dropdown-item">
                      Sales Pipeline
                    </Link>
                    <Link to="#" className="dropdown-item">
                      Email
                    </Link>
                    <Link to="#" className="dropdown-item">
                      Chats
                    </Link>
                    <Link to="#" className="dropdown-item">
                      Operational
                    </Link>
                  </div>
                </div>
                <div className="dropdown">
                  <Link
                    className="dropdown-toggle"
                    data-bs-toggle="dropdown"
                    to="#"
                  >
                    Last 3 months
                  </Link>
                  <div className="dropdown-menu dropdown-menu-end">
                    <Link to="#" className="dropdown-item">
                      Last 3 months
                    </Link>
                    <Link to="#" className="dropdown-item">
                      Last 6 months
                    </Link>
                    <Link to="#" className="dropdown-item">
                      Last 12 months
                    </Link>
                  </div>
                </div>
              </div>
            </div>
          </div>
          <div className="card-body ">
          <div id="won-chart">
                        {" "}
                        <Chart
                          options={chartOptions2}
                          series={chartOptions2.series}
                          type={chartOptions2.chart.type}
                          height={chartOptions2.chart.height}
                        />
                      </div>
          </div>
        </div>
      </div> */}
    </div>
  </div>
</div>

    </div>
  );
};

export default LeadsDashboard;
