import React, { useState } from "react";
import Table from "../../core/common/dataTable/index";
import Select from "react-select";
import DateRangePicker from "react-bootstrap-daterangepicker";
import { Link } from "react-router-dom";
import ImageWithBasePath from "../../core/common/imageWithBasePath";
import CollapseHeader from "../../core/common/collapse-header";
import PrivateServer from "../../helper/PrivateServer";
import { endpoints } from "../../helper/endpoints";
import moment from "moment";
import _ from "lodash";
import useAuth from "../../hooks/useAuth";
import { Modal } from "react-bootstrap";

const Managegroups = () => {
  const { values } = useAuth();
  const [groups, setGroups] = useState([]);
  const [users, setUsers] = useState([]);
  const [searchData, setFilteredSearchData] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [showBulkActionButton, setShowBulkActionButton] = useState(false);
  const [showBulkDeleteModal, setShowBulkDeleteModal] = useState(false);
  const [selectedRows, setSelectedRows] = useState(0);
  const [selectedIds, setSelectedIds] = useState([]);
  const [groupId, setGroupId] = useState("");
  const [formData, setFormData] = useState({
    group_name: "",
    alias: "",
    groupId: "",
    group_description: "",
    group_manager: "",
    group_members: [],
  })

  const [stars, setStars] = useState<{ [key: number]: boolean }>({});

  // const initializeStarsState = () => {
  //   const starsState: { [key: number]: boolean } = {};
  //   users.forEach((item, index) => {
  //     starsState[index] = false;
  //   });
  //   setStars(starsState);
  // };

  const getUsers = async () => {
    try {
      const { Profile } = endpoints;
      const response = await PrivateServer.getData(Profile.view);
  
      if(response?.data) {
        const _data: any = [...new Set(response?.data?.map((x) => ({ label: x?.email, value: x?._id })))]
        setUsers(_data);
      }
    } catch(error) {
      console.log("Error while getting Users -- E: ", error.message);
    }
  }

  const getGroups = async () => {
    try {
      const { Group } = endpoints;
      const response = await PrivateServer.getData(Group.view);
  
      if(response?.data) {
        setGroups([...new Set(response?.data?.map((x: any) => ({ ...x, key: x?.id?.toString() })))]);
        setFilteredSearchData([...new Set(response?.data?.map((x: any) => ({ ...x, key: x?.id?.toString() })))])
      }
    } catch(error) {
      console.log("Error while getting groups -- E: ", error.message);
    }
  }

  React.useEffect(() => {
    // initializeStarsState();

    getUsers();
    getGroups();
  }, []);

  const handleStarToggle = (index: number) => {
    setStars((prevStars) => ({
      ...prevStars,
      [index]: !prevStars[index],
    }));
  };
  
  const handleClose = () => {
    setGroupId("");
    setFormData({
        group_name: "",
        alias: "",
        groupId: "",
        group_description: "",
        group_manager: "",
        group_members: [],
    });
  }

  const handleChange = (e, type="", _name="", _multiple=false) => {    
    if(type == "file") {
      const { name } = e.target;
      setFormData({ ...formData, [name]: e.target?.files[0] });
    } else if(type == "select") {
        if(_multiple) {
            const _users = _.map(e, 'value')
            setFormData({ ...formData, [_name]: _users });
        } else setFormData({ ...formData, [_name]: e?.value });
    } else {
      const { name, value } = e.target; 
      setFormData({ ...formData, [name]: value });
    }
  }

  const handleDeleteGroup = async () => {
    try {
      const { Group } = endpoints;
      const response = await PrivateServer?.deleteData(Group?.delete, groupId);
      if(response) getGroups();
    } catch(err) {
      console.log("Error while deleting group -- E: ", err?.message);
    }
  }

  const handleEditGroup = (values) => {
    setFormData({ ...formData, group_manager: values?.group_manager?._id, group_members: [...new Set(values?.group_members?.map((x) => x?._id))], ..._.omit(values, ["_id", 'group_manager', 'group_members']), groupId: values?._id });
  }

  const handleAddOrUpdateGroup = async () => {
    try {
      const { Group } = endpoints;
      const { status, data } = formData?.groupId !== "" ? await PrivateServer?.patchData(Group.patch, formData?.groupId, formData) : await PrivateServer.postData(Group.create, formData);

      if(status == 200) {
        if(formData?.groupId == "") setFormData({ ...formData, groupId: data?.data?._id })
        getUsers();
      }
    } catch(err) {
      console.log("Error while saving group -- E: ", err?.message);
    }
  }

  const columns = [
    {
      title: "",
      dataIndex: "",
      render: (text: string, record: any, index: number) => (
        <div
          className={`set-star rating-select ${stars[index] ? "filled" : ""}`}
          onClick={() => handleStarToggle(index)}
        >
          <i className="fa fa-star"></i>
        </div>
      ),
    },
    {
      title: "Group Name",
      render: (text: any, record: any) => (
        <h2 className="d-flex align-items-center">
          {/* <Link to="#" className="avatar avatar-sm me-2">
            <ImageWithBasePath
              className="w-auto h-auto"
              src={record.image}
              alt="User Image"
            />
          </Link> */}
          <Link to="#" className="d-flex flex-column">
            {record?.group_name}
          </Link>
        </h2>
      ),
      sorter: true,
    },
    {
      title: "Alias",
      render: (text: any, record: any) => (
        <h2 className="d-flex align-items-center">
          {/* <Link to="#" className="avatar avatar-sm me-2">
            <ImageWithBasePath
              className="w-auto h-auto"
              src={record.image}
              alt="User Image"
            />
          </Link> */}
          <Link to="#" className="d-flex flex-column">
            {record?.alias}
          </Link>
        </h2>
      ),
    },
    {
      title: "Group Manager",
      render: (text: any, record: any) => (
        <h2 className="d-flex align-items-center">
          {/* <Link to="#" className="avatar avatar-sm me-2">
            <ImageWithBasePath
              className="w-auto h-auto"
              src={record.image}
              alt="User Image"
            />
          </Link> */}
          <Link to="#" className="d-flex flex-column">
            {record?.group_manager?.email}
          </Link>
        </h2>
      ),
      sorter: true,
    },
    {
      title: "Group Members",
      render: (text: any, record: any) => (
        <h2 className="d-flex align-items-center">
          {/* <Link to="#" className="avatar avatar-sm me-2">
            <ImageWithBasePath
              className="w-auto h-auto"
              src={record.image}
              alt="User Image"
            />
          </Link> */}
          <Link to="#" className="d-flex flex-column">
            {record?.group_members?.length}
          </Link>
        </h2>
      ),
      sorter: true,
    },
    {
      title: "Action",
      dataIndex: "action",
      render: (text: string, record: any) => (
        <div className="dropdown table-action">
          <Link
            to="#"
            className="action-icon "
            data-bs-toggle="dropdown"
            aria-expanded="false"
          >
            <i className="fa fa-ellipsis-v" />
          </Link>
          <div className="dropdown-menu dropdown-menu-right">
            {values?.permissions?.includes('update') && (<Link
              className="dropdown-item"
              to="#"
              data-bs-target="#offcanvas_edit"
              data-bs-toggle="offcanvas"
              onClick={() => handleEditGroup(record)}
            >
              <i className="ti ti-edit text-blue" /> Edit
            </Link>)}

            {values?.permissions?.includes('delete') && (<Link
              className="dropdown-item"
              to="#"
              data-bs-toggle="modal"
              data-bs-target="#delete_contact"
              onClick={() => setGroupId(record?._id)}
            >
              <i className="ti ti-trash text-danger"></i> Delete
            </Link>)}
          </div>
        </div>
      ),
    },
  ];
  const initialSettings = {
    endDate: new Date("2020-08-11T12:30:00.000Z"),
    ranges: {
      "Last 30 Days": [
        new Date("2020-07-12T04:57:17.076Z"),
        new Date("2020-08-10T04:57:17.076Z"),
      ],
      "Last 7 Days": [
        new Date("2020-08-04T04:57:17.076Z"),
        new Date("2020-08-10T04:57:17.076Z"),
      ],
      "Last Month": [
        new Date("2020-06-30T18:30:00.000Z"),
        new Date("2020-07-31T18:29:59.999Z"),
      ],
      "This Month": [
        new Date("2020-07-31T18:30:00.000Z"),
        new Date("2020-08-31T18:29:59.999Z"),
      ],
      Today: [
        new Date("2020-08-10T04:57:17.076Z"),
        new Date("2020-08-10T04:57:17.076Z"),
      ],
      Yesterday: [
        new Date("2020-08-09T04:57:17.076Z"),
        new Date("2020-08-09T04:57:17.076Z"),
      ],
    },
    startDate: new Date("2020-08-04T04:57:17.076Z"), // Set "Last 7 Days" as default
    timePicker: false,
  };

  const handleSearch = (e) => {
    const { value: _searchTerm } = e?.target;
    setSearchTerm(_searchTerm);
    const _searchData = [...searchData];

    if(searchTerm != "") {
      const searchResults = _.filter(_searchData, (obj) =>
        _.some(obj, (value) =>
          _.isString(value) && _.includes(value.toLowerCase(), searchTerm?.toLowerCase())
        )
      );
      setFilteredSearchData(searchResults)
    } else setFilteredSearchData(searchData);
  }

  const handleBulkOperation = (selectedRows: string | any[]) => {
    if(selectedRows?.length > 0) {
      setShowBulkActionButton(true);
      setSelectedRows(selectedRows?.length)
      setSelectedIds(selectedRows)
    } else {
      setShowBulkActionButton(false);
      setSelectedRows(0)
      setSelectedIds([])
    }
  }

  const handleBulkDelete = async () => {
    const { Group } = endpoints;
    const deleted = await PrivateServer.deleteBulkData(Group?.delete_bulk, selectedIds)
    if(deleted) {
      setShowBulkActionButton(false);
      setShowBulkDeleteModal(false);
    }
  }

  return (
    <>
      {/* Page Wrapper */}
      <div className="page-wrapper">
        <div className="content">
          <div className="row">
            <div className="col-md-12">
              {/* Page Header */}
              <div className="page-header">
                <div className="row align-items-center">
                  <div className="col-8">
                    <h4 className="page-title">
                      Group<span className="count-title">{users?.length}</span>
                    </h4>
                  </div>
                  <div className="col-4 text-end">
                    <div className="head-icons">
                      <CollapseHeader />
                    </div>
                  </div>
                </div>
              </div>
              {/* /Page Header */}
              <div className="card">
                <div className="card-header">
                  {/* Search */}
                  <div className="row align-items-center">
                    <div className="col-sm-4">
                      <div className="icon-form mb-3 mb-sm-0">
                        <span className="form-icon">
                          <i className="ti ti-search" />
                        </span>
                        <input
                          type="text"
                          className="form-control"
                          placeholder="Search User"
                          onChange={handleSearch}
                        />
                      </div>
                    </div>
                    <div className="col-sm-8">
                      <div className="d-flex align-items-center flex-wrap row-gap-2 justify-content-sm-end">
                        <div className="dropdown me-2">
                          <Link
                            to="#"
                            className="dropdown-toggle"
                            data-bs-toggle="dropdown"
                          >
                            <i className="ti ti-package-export me-2" />
                            Export
                          </Link>
                          <div className="dropdown-menu  dropdown-menu-end">
                            <ul>
                              <li>
                                <Link to="#" className="dropdown-item">
                                  <i className="ti ti-file-type-pdf text-danger me-1" />
                                  Export as PDF
                                </Link>
                              </li>
                              <li>
                                <Link to="#" className="dropdown-item">
                                  <i className="ti ti-file-type-xls text-green me-1" />
                                  Export as Excel{" "}
                                </Link>
                              </li>
                            </ul>
                          </div>
                        </div>
                        {values?.permissions?.includes('create') && (<Link
                          to="#"
                          className="btn btn-primary"
                          data-bs-toggle="offcanvas"
                          data-bs-target="#offcanvas_add"
                        >
                          <i className="ti ti-square-rounded-plus me-2" />
                          Add group
                        </Link>)}
                      </div>
                    </div>
                  </div>
                  {/* /Search */}
                </div>
                <div className="card-body">
                  {/* Filter */}
                  <div className="d-flex align-items-center justify-content-between flex-wrap row-gap-2 mb-4">
                    <div className="d-flex align-items-center flex-wrap row-gap-2">
                      {
                        showBulkActionButton ? 
                        <button
                          className="btn btn-primary"
                          onClick={() => setShowBulkDeleteModal(!showBulkDeleteModal)}
                        >
                          Delete {selectedRows} rows
                        </button> 
                        : ""
                      }
                    </div>
                    <div className="d-flex align-items-center flex-wrap row-gap-2">
                      
                    </div>
                  </div>
                  {/* /Filter */}
                  {/* Manage Users List */}
                  <div className="table-responsive custom-table">
                    <Table columns={columns} dataSource={searchTerm != "" ? searchData : groups} handleBulkAction={handleBulkOperation} />
                  </div>
                  <div className="row align-items-center">
                    <div className="col-md-6">
                      <div className="datatable-length" />
                    </div>
                    <div className="col-md-6">
                      <div className="datatable-paginate" />
                    </div>
                  </div>
                  {/* /Manage Users List */}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      {/* /Page Wrapper */}
      {/* Add Group */}
      <div
        className="offcanvas offcanvas-end offcanvas-large"
        tabIndex={-1}
        id="offcanvas_add"
      >
        <div className="offcanvas-header border-bottom">
          <h5 className="fw-semibold">Add New Group</h5>
          <button
            type="button"
            className="btn-close custom-btn-close border p-1 me-0 d-flex align-items-center justify-content-center rounded-circle"
            data-bs-dismiss="offcanvas"
            aria-label="Close"
            onClick={handleClose}
          >
            <i className="ti ti-x" />
          </button>
        </div>
        <div className="offcanvas-body">
          <form>
            <div>
              {/* Basic Info */}
              <div>
                <div className="row">
                  <div className="col-md-6">
                    <div className="mb-3">
                      <label className="col-form-label">
                        {" "}
                        Group Name <span className="text-danger">*</span>
                      </label>
                      <input type="text" name="group_name" value={formData?.group_name} onChange={handleChange} className="form-control" />
                    </div>
                  </div>
                  <div className="col-md-6">
                    <div className="mb-3">
                      <div className="d-flex justify-content-between align-items-center">
                        <label className="col-form-label">
                          Alias <span className="text-danger">*</span>
                        </label>
                      </div>
                      <input type="text" name="alias" value={formData?.alias} onChange={handleChange} className="form-control" />
                    </div>
                  </div>
                  <div className="col-md-6">
                    <div className="mb-3">
                      <div className="d-flex justify-content-between align-items-center">
                        <label className="col-form-label">
                          Group Description <span className="text-danger">*</span>
                        </label>
                      </div>
                      <input type="text" name="group_description" value={formData?.group_description} onChange={handleChange} className="form-control" />
                    </div>
                  </div>
                  <div className="col-md-6">
                    <div className="mb-3">
                      <label className="col-form-label">
                        Group Manager<span className="text-danger">*</span>
                      </label>
                      <Select
                        classNamePrefix="react-select"
                        className="select"
                        options={users}
                        name="group_manager" 
                        value={{ label: users?.find((x: any) => x?.value == formData?.group_manager)?.label, value: formData?.group_manager }} 
                        onChange={(value) => handleChange(value, "select", "group_manager")}
                      />
                    </div>
                  </div>
                  <div className="col-md-6">
                    <div className="mb-3">
                      <label className="col-form-label">
                        Group Members<span className="text-danger">*</span>
                      </label>
                      <Select
                        isMulti={true}
                        name="tax"
                        onChange={(value) => handleChange(value, "select", "group_members", true)}
                        value={_.map(formData?.group_members, (_value) => ({
                            label: users?.find((x: any) => x?.value == _value )?.label, // Converts 'create' to 'Create'
                            _value,
                        }))}
                        className="select2" 
                        classNamePrefix="react-select"
                        options={users}
                        placeholder="Choose"
                    />
                    </div>
                  </div>
                </div>
              </div>
              {/* /Basic Info */}
            </div>
            <div className="d-flex align-items-center justify-content-end">
              <Link
                to="#"
                className="btn btn-light me-2"
                data-bs-dismiss="offcanvas"
                onClick={handleClose}
              >
                Cancel
              </Link>
              <button type="button" className="btn btn-primary" onClick={handleAddOrUpdateGroup}>
                Create
              </button>
            </div>
          </form>
        </div>
      </div>
      {/* /Add Group */}

      {/* Edit Group */}
      <div
        className="offcanvas offcanvas-end offcanvas-large"
        tabIndex={-1}
        id="offcanvas_edit"
      >
        <div className="offcanvas-header border-bottom">
          <h5 className="fw-semibold">Edit Group</h5>
          <button
            type="button"
            className="btn-close custom-btn-close border p-1 me-0 d-flex align-items-center justify-content-center rounded-circle"
            data-bs-dismiss="offcanvas"
            aria-label="Close"
            onClick={handleClose}
          >
            <i className="ti ti-x" />
          </button>
        </div>
        <div className="offcanvas-body">
          <form>
            <div>
              {/* Basic Info */}
              <div>
                <div className="row">
                  <div className="col-md-6">
                    <div className="mb-3">
                      <label className="col-form-label">
                        {" "}
                        Group Name <span className="text-danger">*</span>
                      </label>
                      <input type="text" name="group_name" value={formData?.group_name} onChange={handleChange} className="form-control" />
                    </div>
                  </div>
                  <div className="col-md-6">
                    <div className="mb-3">
                      <div className="d-flex justify-content-between align-items-center">
                        <label className="col-form-label">
                          Alias <span className="text-danger">*</span>
                        </label>
                      </div>
                      <input type="text" name="alias" value={formData?.alias} onChange={handleChange} className="form-control" />
                    </div>
                  </div>
                  <div className="col-md-6">
                    <div className="mb-3">
                      <div className="d-flex justify-content-between align-items-center">
                        <label className="col-form-label">
                          Group Description <span className="text-danger">*</span>
                        </label>
                      </div>
                      <input type="text" name="group_description" value={formData?.group_description} onChange={handleChange} className="form-control" />
                    </div>
                  </div>
                  <div className="col-md-6">
                    <div className="mb-3">
                      <label className="col-form-label">
                        Group Manager<span className="text-danger">*</span>
                      </label>
                      <Select
                        classNamePrefix="react-select"
                        className="select"
                        options={users}
                        name="group_manager" 
                        value={{ label: users?.find((x: any) => x?.value == formData?.group_manager)?.label, value: formData?.group_manager }} 
                        onChange={(value) => handleChange(value, "select", "group_manager")}
                      />
                    </div>
                  </div>
                  <div className="col-md-6">
                    <div className="mb-3">
                      <label className="col-form-label">
                        Group Members<span className="text-danger">*</span>
                      </label>
                      <Select
                        isMulti={true}
                        name="tax"
                        onChange={(value) => handleChange(value, "select", "group_members", true)}
                        value={_.map(formData?.group_members, (_value) => ({
                            label: users?.find((x: any) => x?.value == _value )?.label, // Converts 'create' to 'Create'
                            _value,
                        }))}
                        className="select2" 
                        classNamePrefix="react-select"
                        options={users}
                        placeholder="Choose"
                    />
                    </div>
                  </div>
                </div>
              </div>
              {/* /Basic Info */}
            </div>
            <div className="d-flex align-items-center justify-content-end">
              <Link
                to="#"
                className="btn btn-light me-2"
                data-bs-dismiss="offcanvas"
                onClick={handleClose}
              >
                Cancel
              </Link>
              <button
                type="button"
                data-bs-dismiss="offcanvas"
                className="btn btn-primary"
                onClick={handleAddOrUpdateGroup}
              >
                Update
              </button>
            </div>
          </form>
        </div>
      </div>
      {/* /Edit Group */}
      {/* Delete Group */}
      <div className="modal fade" id="delete_contact" role="dialog">
        <div className="modal-dialog modal-dialog-centered">
          <div className="modal-content">
            <div className="modal-body">
              <div className="text-center">
                <div className="avatar avatar-xl bg-danger-light rounded-circle mb-3">
                  <i className="ti ti-trash-x fs-36 text-danger" />
                </div>
                <h4 className="mb-2">Remove group?</h4>
                <p className="mb-0">Are you sure you want to remove it</p>
                <div className="d-flex align-items-center justify-content-center mt-4">
                  <Link
                    to="#"
                    className="btn btn-light me-2"
                    data-bs-dismiss="modal"
                  >
                    Cancel
                  </Link>
                  <Link to="#" className="btn btn-danger" onClick={handleDeleteGroup}>
                    Yes, Delete it
                  </Link>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      {/* /Delete Group */}
      {/** Bulk Delete Data */}
      <Modal show={showBulkDeleteModal} onHide={() => setShowBulkDeleteModal(false)}>
        <div className="modal-header border-0 m-0 justify-content-end">
          <button
            className="btn-close"
            aria-label="Close"
            onClick={() => {
              setShowBulkDeleteModal(false)
            }}
          >
            <i className="ti ti-x" />
          </button>
        </div>
        <div className="modal-body">
          <div className="success-message text-center">
            <div className="success-popup-icon bg-light-blue">
              <i className="ti ti-user-plus" />
            </div>
            <h3>Are you sure?</h3>
            <p>delete ({selectedRows})selected rows</p>
            <div className="col-lg-12 text-center modal-btn">
              <Link
                to="#"
                className="btn btn-light"
                onClick={() => setShowBulkDeleteModal(false)}
              >
                Cancel
              </Link>
              <Link to="#" className="btn btn-primary" onClick={handleBulkDelete}>
                Delete
              </Link>
            </div>
          </div>
        </div>
      </Modal>
      {/** Bulk Delete Data */}
    </>
  );
};

export default Managegroups;
